defaultFormField(
        {String? label,
        IconData? prefix,
        String? hint,
        IconButton? suffix,
        bool? enabled = true,
        int? maxLength,
        String? validatorText,
        TextInputType? type,
        void Function()? suffixFunction,
        FormFieldValidator? validator,
        bool obscureText = false,
        required TextEditingController controller}) =>
    TextFormField(
      onTapOutside: (event) {
        FocusManager.instance.primaryFocus?.unfocus();
      },
      controller: controller,
      keyboardType: type,
      enabled: enabled,
      cursorColor: ColorManager.primary,
      obscureText: obscureText,
      maxLines: maxLength,
      style: TextStyle(color: ColorManager.black),
      decoration: InputDecoration(
          disabledBorder: OutlineInputBorder(
            borderSide: BorderSide(color: ColorManager.secondary),
            borderRadius: BorderRadius.circular(10.sp),
          ),
          focusedBorder: OutlineInputBorder(
            borderSide: BorderSide(color: ColorManager.secondary),
            borderRadius: BorderRadius.circular(10.sp),
          ),
          enabledBorder: OutlineInputBorder(
            borderRadius: BorderRadius.circular(10.sp),
          ),
          errorStyle: const TextStyle(fontSize: 0.01),
          fillColor: ColorManager.white,
          suffixIcon: suffix,
          labelText: label,
          helperText: hint,
          labelStyle: TextStyle(
            color: ColorManager.secondary,
          )),
      validator: validator,
    );

defaultToast({
  required String msg,
}) {
  Fluttertoast.showToast(
    msg: msg,
    backgroundColor: ColorManager.primary,
    textColor: ColorManager.white,
    toastLength: Toast.LENGTH_SHORT,
  );
}

warnToast({
  required String msg,
}) {
  Fluttertoast.showToast(
    msg: msg,
    backgroundColor: ColorManager.secondary,
    textColor: ColorManager.white,
    toastLength: Toast.LENGTH_SHORT,
  );
}

errorToast({
  required String msg,
}) {
  Fluttertoast.showToast(
    msg: msg,
    backgroundColor: ColorManager.error,
    textColor: ColorManager.white,
    toastLength: Toast.LENGTH_SHORT,
  );
}

Widget defaultButton({
  required VoidCallback onPressed,
  required String text,
  double? width = double.infinity,
  double? height,
  Color? textColor,
  Color? buttonColor,
  Color? borderColor,
  double? fontSize,
  FontWeight? fontWeight,
}) =>
    Container(
      decoration: BoxDecoration(
        color: buttonColor ?? ColorManager.primary,
        border: Border.all(
          width: 2,
          color: borderColor ?? ColorManager.black.withOpacity(0),
        ),
        borderRadius: BorderRadius.circular(20.sp),
      ),
      width: width,
      height: height ?? 8.h,
      child: MaterialButton(
        onPressed: onPressed,
        child: Text(
          text,
          style: TextStyle(
            fontSize: fontSize ?? 15.sp,
            fontWeight: fontWeight,
            color: textColor ?? ColorManager.white,
          ),
        ),
      ),
    );

Widget listAmc(
    {required String text, required MainBloc bloc, required int index}) {
  List<int> list = [];
  return BlocBuilder<MainBloc, MainState>(
    builder: (context, state) {
      if (state is AddToListAmcReportState) {
        list = state.list;
      }
      if (state is RemoveFromListAmcReportState) {
        list = state.list;
      }
      return Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            "$index)",
            style: TextStyle(
                color: ColorManager.secondary,
                fontSize: 18.sp,
                fontWeight: FontWeight.w800),
          ),
          SizedBox(
            width: 3.w,
          ),
          Expanded(
              child: Text(
            text,
            style: TextStyle(
                color: ColorManager.secondary,
                fontSize: 14.sp,
                fontWeight: FontWeight.w800),
          )),
          InkWell(
            onTap: () {
              bloc.add(AddToListAmcReport(index: index, list: list));
            },
            child: Icon(
              list.contains(index)
                  ? Icons.check_box
                  : Icons.check_box_outline_blank,
              size: 25.sp,
              color: ColorManager.secondary,
            ),
          ),
        ],
      );
    },
  );
}

