  if (title != null && width != null) {
    return ClipPath(
      clipper: CurveClipper(width: width),
      child: Stack(
        alignment: Alignment.bottomCenter,
        children: [
          Stack(
            children: [
              Container(
                color: ColorManager.primary,
                height: height.h,
                width: double.infinity,
              ),
              Image.asset(
                "assets/images/Subtraction.png",
                height: height.h,
                width: double.infinity,
                fit: BoxFit.fill,
              ),
            ],
          ),
          Padding(
            padding: EdgeInsetsDirectional.only(bottom: 5.h),
            child: Text(
              title,
              style: TextStyle(
                  fontWeight: FontWeight.bold,
                  fontSize: fontSize ?? 25.sp,
                  color: ColorManager.white),
            ),
          ),
        ],
      ),
    );
  } else {
    return Stack(
      children: [
        Container(
          color: ColorManager.primary,
          height: height.h,
          width: double.infinity,
        ),
        Image.asset(
          "assets/images/Subtraction.png",
          height: height.h,
          width: double.infinity,
          fit: BoxFit.fill,
        ),
      ],
    );
  }
}

