List<Widget> amcCardWidgets({
  required List<AmcCard> amcCards,
  required MainBloc bloc,
  required BuildContext context,
}) {
  List<Widget> list = [];
  int index = 0;
  for (AmcCard amcCard in amcCards) {
    if (amcCard.totalAc > 0) {
      list.add(amcCardWidget(
          amcCard: amcCard,
          id: amcCard.id,
          context: context,
          index: index,
          bloc: bloc));
    }
    index++;
  }
  return list;
}

