Uint8List stringToByteList(String encodedImage) {
  final decodedBytes = base64Decode(encodedImage);
  return Uint8List.fromList(decodedBytes);
}

List<Uint8List> stringsListToByteList(List<String> encodedImages) {
  List<Uint8List> photos = [];
  for (String encodedImage in encodedImages) {
    photos.add(stringToByteList(encodedImage));
  }
  return photos;
}

showDialogSuccess({
  required BuildContext context,
  required String text,
  required VoidCallback onPressed,
}) {
  return showDialog(
    barrierDismissible: false,
    context: context,
    builder: (BuildContext context) {
      return AlertDialog(
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(25.sp),
        ),
        title: Text(
          text,
          style: TextStyle(
            color: ColorManager.primary,
          ),
        ),
        actions: [
          TextButton(
              onPressed: onPressed,
              child: Text(
                "Okay",
                style: TextStyle(color: ColorManager.secondary),
              )),
        ],
      );
    },
  );
}

showDialogLoading({
  required BuildContext context,
}) {
  return showDialog(
    barrierDismissible: false,
    context: context,
    builder: (BuildContext context) {
      return AlertDialog(
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(25.sp),
        ),
        title: const Center(child: CircularProgressIndicator()),
      );
    },
  );
}

getLastSegment(String url) {
  RegExp regExp = RegExp(r'\/(\d+)$');
  Match? match = regExp.firstMatch(url);
  String lastNumber = match!.group(1)!;
  return lastNumber;
}
